    type Row = std::collections::BTreeMap<String, (Option<String>, Option<i64>, Option<bool>)>;

    let mut current = rows;

    {
        let mut chosen_by_key = std::collections::BTreeMap::<String, Row>::new();
        let mut key_order = Vec::<String>::new();
        for row in current.into_iter() {
            let key = row.get("name").unwrap().0.clone().unwrap();
            let score = row.get("delta").unwrap().1.unwrap();
            if !chosen_by_key.contains_key(&key) {
                chosen_by_key.insert(key.clone(), row);
                key_order.push(key);
                continue;
            }
            let current_best = chosen_by_key.get(&key).unwrap().get("delta").unwrap().1.unwrap();
            let should_replace = score >= current_best;
            if should_replace {
                chosen_by_key.insert(key.clone(), row);
            }
        }
        let mut next_rows = Vec::new();
        for key in key_order.into_iter() {
            next_rows.push(chosen_by_key.remove(&key).unwrap());
        }
        current = next_rows;
    }

    {
        let mut next_rows = Vec::new();
        for row in current.into_iter() {
            let mut projected = Row::new();
            projected.insert("name".to_string(), row.get("name").unwrap().clone());
            projected.insert("delta".to_string(), row.get("delta").unwrap().clone());
            projected.insert("amount".to_string(), row.get("amount").unwrap().clone());
            next_rows.push(projected);
        }
        current = next_rows;
    }

    current
}

