    using ScalarValue = std::variant<std::string, long long, bool>;
    using Row = std::map<std::string, std::variant<std::string, long long, bool>>;

    auto current = rows;

    {
        std::map<std::string, Row> chosenByKey;
        std::vector<std::string> keyOrder;
        for (const auto& row : current) {
