            if (chosenByKey.find(key) == chosenByKey.end()) {
                chosenByKey.emplace(key, row);
                keyOrder.push_back(key);
                continue;
            }
            auto currentBest = std::get<long long>(chosenByKey.at(key).at("delta"));
            auto shouldReplace = score >= currentBest;
            if (shouldReplace) {
                chosenByKey[key] = row;
            }
        }
        std::vector<Row> nextRows;
        for (const auto& key : keyOrder) {
            nextRows.push_back(chosenByKey.at(key));
        }
        current = nextRows;
    }

    {
        std::vector<Row> nextRows;
        for (const auto& row : current) {
            Row projected;
            projected.insert({"name", row.at("name")});
            projected.insert({"delta", row.at("delta")});
            projected.insert({"amount", row.at("amount")});
            nextRows.push_back(projected);
        }
        current = nextRows;
    }

    return current;
