	cloneRow := func(row map[string]any) map[string]any {
		copied := map[string]any{}
		for k, v := range row {
			copied[k] = v
		}
		return copied
	}

	var current []map[string]any
	for _, row := range rows {
		current = append(current, cloneRow(row))
	}

	{
		var nextRows []map[string]any
		for _, row := range current {
			if row["visible"].(bool) == false {
				nextRows = append(nextRows, cloneRow(row))
			}
		}
		current = nextRows
	}

	{
		chosenByKey := map[struct{ field0 string; field1 string }]map[string]any{}
		var keyOrder []struct{ field0 string; field1 string }
		for _, row := range current {
			key := struct{ field0 string; field1 string }{field0: row["kind"].(string), field1: row["group"].(string)}
			score := int(row["points"].(float64))
			existingRow, exists := chosenByKey[key]
			if !exists {
				chosenByKey[key] = cloneRow(row)
				keyOrder = append(keyOrder, key)
				continue
			}
			currentBest := int(existingRow["points"].(float64))
			shouldReplace := score >= currentBest
			if shouldReplace {
				chosenByKey[key] = cloneRow(row)
			}
		}
		current = []map[string]any{}
		for _, key := range keyOrder {
			current = append(current, chosenByKey[key])
		}
	}

	{
		var nextRows []map[string]any
		for _, row := range current {
			projected := map[string]any{"kind": row["kind"], "group": row["group"], "points": row["points"], "score": row["score"]}
			nextRows = append(nextRows, projected)
		}
		current = nextRows
	}

	return current
}

