    type ScalarValue = (Option<String>, Option<i64>, Option<bool>);
    type Row = std::collections::BTreeMap<String, (Option<String>, Option<i64>, Option<bool>)>;

    let mut current = rows;

    {
        let mut counts_by_key = std::collections::BTreeMap::<(String, String), Row>::new();
        let mut seen_values_by_key = std::collections::BTreeMap::<(String, String), std::collections::BTreeSet<ScalarValue>>::new();
        let mut key_order = Vec::<(String, String)>::new();
        for row in current.into_iter() {
            let key = (row.get("tag").unwrap().0.clone().unwrap(), row.get("bucket").unwrap().0.clone().unwrap());
            if !counts_by_key.contains_key(&key) {
                let mut entry = Row::new();
                entry.insert("tag".to_string(), row.get("tag").unwrap().clone());
                entry.insert("bucket".to_string(), row.get("bucket").unwrap().clone());
                entry.insert("distinct_count".to_string(), (None, Some(0i64), None));
                counts_by_key.insert(key.clone(), entry);
                seen_values_by_key.insert(key.clone(), std::collections::BTreeSet::<ScalarValue>::new());
                key_order.push(key.clone());
            }
            let value = row.get("score").unwrap().clone();
            let seen_for_key = seen_values_by_key.get_mut(&key).unwrap();
            if !seen_for_key.contains(&value) {
                seen_for_key.insert(value);
                let entry = counts_by_key.get_mut(&key).unwrap();
                if let (None, Some(n), None) = entry.get_mut("distinct_count").unwrap() { *n += 1; }
            }
        }
        let mut next_rows = Vec::new();
        for key in key_order.into_iter() {
            next_rows.push(counts_by_key.remove(&key).unwrap());
        }
        current = next_rows;
    }

    {
        let mut next_rows = Vec::new();
        for row in current.into_iter() {
            if row.get("distinct_count").unwrap().1.unwrap() >= 3 {
                next_rows.push(row);
            }
        }
        current = next_rows;
    }

    {
        let mut next_rows = Vec::new();
        for row in current.into_iter() {
            let mut projected = Row::new();
            projected.insert("tag".to_string(), row.get("tag").unwrap().clone());
            projected.insert("bucket".to_string(), row.get("bucket").unwrap().clone());
            projected.insert("distinct_count".to_string(), row.get("distinct_count").unwrap().clone());
