    type Row = std::collections::BTreeMap<String, (Option<String>, Option<i64>, Option<bool>)>;

    let mut current = rows;

    {
        let mut next_rows = Vec::new();
        for row in current.into_iter() {
            if row.get("points").unwrap().1.unwrap() >= 2 {
                next_rows.push(row);
            }
        }
        current = next_rows;
    }

    {
        let mut totals_by_key = std::collections::BTreeMap::<String, Row>::new();
        let mut key_order = Vec::<String>::new();
        for row in current.into_iter() {
            let key = row.get("group").unwrap().0.clone().unwrap();
            if !totals_by_key.contains_key(&key) {
                let mut entry = Row::new();
                entry.insert("group".to_string(), row.get("group").unwrap().clone());
                entry.insert("total".to_string(), (None, Some(0i64), None));
                totals_by_key.insert(key.clone(), entry);
                key_order.push(key.clone());
