            let delta = row.get("points").unwrap().1.unwrap();
            if let (None, Some(n), None) = entry.get_mut("total").unwrap() { *n += delta; }
        }
        let mut next_rows = Vec::new();
        for key in key_order.into_iter() {
            next_rows.push(totals_by_key.remove(&key).unwrap());
        }
        current = next_rows;
    }

    {
        let mut next_rows = Vec::new();
        for row in current.into_iter() {
            if row.get("total").unwrap().1.unwrap() >= 1 {
                next_rows.push(row);
            }
        }
        current = next_rows;
