        let mut next_rows = Vec::new();
        for row in current.into_iter() {
            let mut projected = Row::new();
            projected.insert("group".to_string(), row.get("group").unwrap().clone());
            projected.insert("total".to_string(), row.get("total").unwrap().clone());
            next_rows.push(projected);
        }
        current = next_rows;
    }

    current
}

